## 1. LoadingManager

单例负责整个加载流程。

```csharp
using UnityEngine;
using UnityEngine.SceneManagement;
using System.Collections;

public class LoadingManager : MonoBehaviour
{
    public static LoadingManager Instance;

    private AsyncOperation _loadingOp;
    private bool _isLoading;
    private bool _cancelRequested;

    public bool IsLoading => _isLoading;
    public float Progress => _loadingOp == null ? 0 : _loadingOp.progress;

    private void Awake()
    {
        if (Instance == null)
        {
            Instance = this;
            DontDestroyOnLoad(gameObject);
        }
        else
        {
            Destroy(gameObject);
        }
    }

    public void LoadScene(string sceneName)
    {
        if (_isLoading)
        {
            Debug.Log("已经在加载中");
            return;
        }

        StartCoroutine(LoadRoutine(sceneName));
    }

    public void CancelLoad()
    {
        if (!_isLoading)
            return;

        _cancelRequested = true;

        if (_loadingOp != null)
            _loadingOp.allowSceneActivation = false;
    }

    private IEnumerator LoadRoutine(string sceneName)
    {
        _isLoading = true;
        _cancelRequested = false;

        yield return SceneManager.LoadSceneAsync("LoadingScene");

        yield return null;

        _loadingOp = SceneManager.LoadSceneAsync(sceneName);
        _loadingOp.allowSceneActivation = false;

        while (_loadingOp.progress < 0.9f)
        {
            if (_cancelRequested)
            {
                yield return SceneManager.LoadSceneAsync("MainMenu");
                _isLoading = false;
                yield break;
            }

            yield return null;
        }

        if (_cancelRequested)
        {
            yield return SceneManager.LoadSceneAsync("MainMenu");
            _isLoading = false;
            yield break;
        }

        _loadingOp.allowSceneActivation = true;

        while (!_loadingOp.isDone)
            yield return null;

        _isLoading = false;
    }
}
```

